  justify-content: center;
  padding: 20px;
}

main {
  width: 100%;
  max-width: 500px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
  padding: 40px;
}

header {
  margin-bottom: 32px;
  text-align: center;
}

h1 {
  font-size: 28px;
  font-weight: 700;
  color: #1a202c;
  margin-bottom: 12px;
}

.subtitle {
  font-size: 16px;
  color: #4a5568;
  line-height: 1.5;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-notice {
  font-size: 14px;
  color: #4a5568;
  margin-bottom: 8px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

label {
  font-weight: 600;
  font-size: 14px;
  color: #2d3748;
  display: flex;
  align-items: center;
  gap: 4px;
}

label span[aria-hidden="true"] {
  color: #e53e3e;
  font-weight: 700;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  padding: 12px 16px;
  border: 2px solid #cbd5e0;
  border-radius: 6px;
  font-size: 16px;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
  background-color: #fff;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  outline: none;
  border-color: #3182ce;
  box-shadow: 0 0 0 3px rgba(49, 130, 206, 0.1);
}

input[aria-invalid="true"] {
  border-color: #e53e3e;
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(229, 62, 62, 0.1);
}

input:disabled {
  background-color: #edf2f7;
  color: #a0aec0;
  cursor: not-allowed;
}

.help-text {
  font-size: 13px;
  color: #718096;
  margin-top: -4px;
  line-height: 1.4;
}

.error-message {
  font-size: 13px;
  color: #e53e3e;
  font-weight: 500;
  min-height: 20px;
  line-height: 1.4;
}

.error-message:empty {
  display: none;
}

.submit-btn {
  padding: 12px 24px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  margin-top: 8px;
}

.submit-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(102, 126, 234, 0.4);
}

.submit-btn:active {
  transform: translateY(0);
}

.submit-btn:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.3);
}

.submit-btn:disabled {
  background: #cbd5e0;
  cursor: not-allowed;
  transform: none;
}

.submit-message {
  min-height: 20px;
  padding: 12px;
  border-radius: 6px;
  font-size: 14px;
  text-align: center;
  display: none;
}

.submit-message.success {
  display: block;
  background-color: #f0fff4;
  color: #22543d;
  border: 1px solid #9ae6b4;
}

.submit-message.error {
  display: block;
  background-color: #fff5f5;
  color: #742a2a;
  border: 1px solid #fc8181;
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  input[type="text"],
  input[type="email"],
  input[type="tel"] {
    border-width: 3px;
  }

  .submit-btn {
    border: 2px solid currentColor;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  input[type="text"],
  input[type="email"],
  input[type="tel"],
  .submit-btn {
    transition: none;
  }
}

/* Narrow viewport */
@media (max-width: 480px) {
  main {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
  }

