AssistantMessageToolRequest(name='create', tool_call_id='tooluse_M7FXFLKuSwmHA26dSv2jeE', arguments={'file_text': "class ContactForm {
  constructor() {
    this.form = document.getElementById('contactForm');
    this.fields = {
      fullName: {
        input: document.getElementById('fullName'),
        errorEl: document.getElementById('fullName-error'),
        validators: [this.validateRequired]
      },
      email: {
        input: document.getElementById('email'),
        errorEl: document.getElementById('email-error'),
        validators: [this.validateRequired, this.validateEmail]
      },
      phone: {
        input: document.getElementById('phone'),
        errorEl: document.getElementById('phone-error'),
        validators: [this.validatePhone]
      }
    };
    this.submitMessage = document.getElementById('submitMessage');
    this.init();
  }

  init() {
    this.form.addEventListener('submit', (e) => this.handleSubmit(e));

    Object.values(this.fields).forEach(field => {
      field.input.addEventListener('blur', () => this.validateField(field));
      field.input.addEventListener('input', () => {
        if (field.input.getAttribute('aria-invalid') === 'true') {
          this.validateField(field);
        }
      });
    });
  }

  validateRequired = (value) => {
    if (!value.trim()) {
      return 'Error: This field is required.';
    }
    return '';
  };

  validateEmail = (value) => {
    if (!value) return '';
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      return 'Error: Enter a valid email address (e.g., name@example.com).';
    }
    return '';
  };

  validatePhone = (value) => {
    if (!value) return '';
    const phoneRegex = /^[\d\s\-()+.]*\d[\d\s\-()+.]*$|^[+]?[\d\s\-()]*$/;
    if (!phoneRegex.test(value)) {
      return 'Error: Enter a valid phone number.';
    }
    return '';
  };

  validateField(field) {
    const value = field.input.value;
    let error = '';

    for (const validator of field.validators) {
      error = validator(value);
      if (error) break;
    }

    if (error) {
      field.input.setAttribute('aria-invalid', 'true');
      field.errorEl.textContent = error;
    } else {
      field.input.setAttribute('aria-invalid', 'false');
      field.errorEl.textContent = '';
    }

    return !error;
  }

  validateForm() {
    const results = Object.values(this.fields).map(field => this.validateField(field));
    return results.every(isValid => isValid);
  }

  handleSubmit(e) {
    e.preventDefault();

    this.submitMessage.textContent = '';
    this.submitMessage.className = 'submit-message';

    if (!this.validateForm()) {
      const firstInvalid = Object.values(this.fields).find(
        field => field.input.getAttribute('aria-invalid') === 'true'
      );
      if (firstInvalid) {
        firstInvalid.input.focus();
      }
      return;
    }

    const formData = {
      fullName: this.fields.fullName.input.value,
      email: this.fields.email.input.value,
      phone: this.fields.phone.input.value
    };

    console.log('Form submitted:', formData);

    this.submitMessage.textContent = 'Message sent successfully! We\'ll be in touch soon.';
    this.submitMessage.className = 'submit-message success';

    this.form.reset();
    Object.values(this.fields).forEach(field => {
      field.input.setAttribute('aria-invalid', 'false');
      field.errorEl.textContent = '';
    });
  }
}

document.addEventListener('DOMContentLoaded', () => {
  new ContactForm();
});
