const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const axeCore = require('axe-core');

async function runAccessibilityTests() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.resolve(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Inject axe-core
  await page.addScriptTag({ content: axeCore.source });

  // Run accessibility tests
  const results = await page.evaluate(async () => {
    return await window.axe.run({
      rules: {
        'color-contrast': { enabled: true },
        'focus-visible': { enabled: true },
        'form-field-multiple-labels': { enabled: true },
        'image-alt': { enabled: true },
        'label': { enabled: true },
        'aria-required-attr': { enabled: true }
      }
    });
  });

  await browser.close();

  // Separate WCAG and best-practice violations
  const wcagViolations = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bpViolations = results.violations.filter(v => v.tags.includes('best-practice'));

  // Format output
  const output = {
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bpViolations.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  };

  console.log(JSON.stringify(output, null, 2));

  return wcagViolations.length === 0 ? 0 : 1;
}

runAccessibilityTests().then(code => process.exit(code)).catch(err => {
  console.error('Test error:', err.message);
  process.exit(2);
});

